head.b:skin:
/* SaeGreen 1.0.1 — editable source. */
/*
<Variable name="accent" description="Warna hijau utama" type="color" default="#3dcc58" value="#3dcc58"/>
<Variable name="ink" description="Warna teks" type="color" default="#202124" value="#202124"/>
*/
:root{--green:$(accent);--ink:$(ink);--muted:#5f6368;--line:#dadce0;--paper:#fff;--soft:#f8f9fa;--mint:#ecfff1;--radius:8px;--width:1260px;--header:64px}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:88px;-webkit-text-size-adjust:100%}body{margin:0;background:var(--paper);color:var(--ink);font:400 16px/1.6 'Google Sans',Arial,Helvetica,sans-serif;overflow-wrap:anywhere}a{color:inherit;text-decoration:none}a:hover{color:#219340}button,input,select{font:inherit}button,a,input,summary{touch-action:manipulation}button{cursor:pointer;color:inherit}button:disabled{cursor:default;opacity:.35}button{border:0;background:none}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #2884f4;outline-offset:4px}img{max-width:100%;height:auto;vertical-align:middle}svg{width:24px;height:24px;vertical-align:middle;flex:none}h1,h2,h3,p,figure{margin:0}h1,h2,h3{line-height:1.25;letter-spacing:-.45px}ul{margin:0;padding:0;list-style:none}.section,.widget,.widget-content{margin:0;padding:0;min-width:0}[hidden]{display:none!important}.sg-cfg{display:none!important}.sg-wrap{max-width:calc(var(--width) + 64px);padding:0 32px;margin:auto}.sg-sr{position:absolute!important;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.sg-skip{position:fixed;left:12px;top:-80px;z-index:1000;background:#fff;padding:10px;border:2px solid var(--green)}.sg-skip:focus{top:10px}.sg-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 24px;background:var(--green);border:1px solid transparent;border-radius:3px;color:#fff;line-height:1.4;white-space:nowrap}.sg-btn:hover{color:#fff;background:#2ab845}.sg-pill{display:inline-block;border:1px solid var(--line);border-radius:30px;padding:8px 18px;font-size:13px;background:var(--paper)}.sg-pill:hover{background:var(--soft);color:var(--ink)}.sg-icon{width:42px;height:44px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;flex:none;color:var(--muted)}.sg-icon:hover{background:var(--soft)}
/* Header and editable navigation */
.sg-header{position:sticky;top:0;z-index:50;background:var(--paper);box-shadow:0 2px 5px #0003}.sg-header-row{height:64px;padding:0 36px 0 14px;display:flex;align-items:center;gap:20px}.sg-brand{display:flex;align-items:center;gap:7px;flex:none;white-space:nowrap;font-size:23px;font-weight:700;letter-spacing:-1.1px;color:#194b2b}.sg-brand:hover{color:#194b2b}.sg-leaf{width:28px;height:32px;color:#31b34a}.sg-brand-image{width:auto;max-width:170px;max-height:38px}.sg-tagline{font-size:22px;font-weight:400;color:var(--muted);white-space:nowrap;letter-spacing:0}.sg-nav{display:flex;align-items:stretch;height:64px;font-size:14px;gap:10px;flex:1}.sg-nav>li{display:flex;align-items:stretch}.sg-nav>li>a,.sg-nav>li>button{display:flex;align-items:center;gap:5px;padding:0 14px;border-bottom:2px solid transparent}.sg-nav>li>a[aria-current=page]{border-color:#4285f4;color:var(--ink)}.sg-nav button[aria-expanded=true]{background:var(--soft)}.sg-chevron{width:14px;height:14px}.sg-actions{display:flex;align-items:center;gap:12px;margin-left:auto}.sg-mobile-toggle{display:none}.sg-mega{position:absolute;left:0;right:0;top:64px;background:var(--paper);box-shadow:0 5px 8px #0002;padding:36px 44px 24px;max-height:calc(100dvh - 64px);overflow:auto}.sg-mega-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:60px}.sg-mega h3{font-size:12px;letter-spacing:1px;text-transform:uppercase;font-weight:500;color:var(--muted);padding-bottom:16px;border-bottom:1px solid var(--line);margin-bottom:16px}.sg-mega li a{display:block;padding:8px 0;font-size:14px;color:var(--muted)}.sg-mega li a:hover{color:#219340}.sg-mega-close{position:absolute;top:10px;right:16px}.sg-mega-bottom{display:flex;justify-content:flex-end;margin-top:30px;border-top:1px solid var(--line);padding-top:20px;color:#219340}.sg-more{position:absolute;right:35px;top:66px;min-width:210px;box-shadow:0 4px 16px #0003;border:1px solid var(--line);border-radius:8px;padding:12px;background:var(--paper)}.sg-more a,.sg-more button{display:block;width:100%;text-align:left;padding:10px 14px;font-size:14px}.sg-search{position:absolute;top:64px;left:0;right:0;padding:26px 32px;background:var(--paper);box-shadow:0 5px 10px #0002}.sg-search form{max-width:900px;display:flex;gap:12px;margin:auto}.sg-search input{min-width:0;flex:1;padding:12px 18px;border:1px solid var(--line);border-radius:4px;background:var(--soft);color:var(--ink)}.sg-readbar{display:none;flex:1;min-width:0;font-size:14px}.sg-readbar-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sg-header.reading .sg-readbar{display:flex;align-items:center;justify-content:space-between;gap:16px}.sg-header.reading .sg-nav,.sg-header.reading .sg-actions{display:none}.sg-progress{position:absolute;bottom:0;left:0;width:100%;height:3px;transform-origin:left;transform:scaleX(0);background:var(--green);pointer-events:none}
.sg-region{position:relative}.sg-region select{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.sg-region:focus-within{outline:3px solid #2884f4;outline-offset:2px}.sg-readbar .sg-pill{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;flex:none}.sg-readbar-title{min-width:0}
/* Home gallery */
.sg-gallery{margin:20px auto 40px}.sg-slides{position:relative;height:340px;overflow:hidden;border-radius:20px;background:#e7f0ea;isolation:isolate}.sg-slide{position:absolute;inset:0;opacity:0;visibility:hidden;transition:opacity .55s ease;display:block;color:#fff}.sg-slide.active{opacity:1;visibility:visible;z-index:1}.sg-slide:hover{color:#fff}.sg-slide>img{width:100%;height:100%;object-fit:cover}.sg-slide:after{content:'';position:absolute;inset:42% 0 0;background:linear-gradient(transparent,#202124b8)}.sg-slide-caption{position:absolute;z-index:1;bottom:24px;left:28px;right:140px}.sg-slide-caption small{display:inline-block;font-size:11px;text-transform:uppercase;font-weight:700;background:#ffffff38;border:1px solid #ffffff60;padding:2px 10px;border-radius:14px;margin-bottom:8px}.sg-slide-caption h2{font-size:22px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sg-gallery-buttons{position:absolute;z-index:3;bottom:18px;right:18px;display:flex;background:#fff;color:#202124;border-radius:28px;box-shadow:0 1px 8px #0002}.sg-gallery-buttons button{width:42px;height:42px;display:grid;place-items:center}.sg-gallery-buttons svg{width:18px}.sg-gallery-buttons button+button{border-left:1px solid #eee}.sg-gallery-track{display:flex;gap:3px;margin:8px 20px 0}.sg-gallery-track button{height:3px;padding:0;flex:1;background:#dadce0}.sg-gallery-track button[aria-current=true]{background:#202124}.sg-fallback-art{height:100%;width:100%;display:grid;place-items:center;background:radial-gradient(circle at 30% 25%,#c1eac4,transparent 55%),linear-gradient(125deg,#f1f8e9,#b2dfdb)}.sg-fallback-art svg{width:100px;height:100px;color:#31a853}
/* Featured story */
.sg-feature{position:relative;max-width:1440px;margin:0 auto 64px;min-height:444px;display:grid;grid-template-columns:63% 37%;align-items:center}.sg-feature-photo{height:444px;overflow:hidden;border-radius:0 0 5px 0;display:block}.sg-feature-photo img{width:100%;height:100%;object-fit:cover}.sg-feature-copy{position:relative;margin:0 21% 0 -48px;padding:36px;background:var(--paper);border:1px solid #e9e9e9;box-shadow:0 2px 7px #0003;border-radius:16px;min-width:0}.sg-eyebrow{font-size:14px;color:#34ad4c;text-transform:uppercase;display:inline-block;margin-bottom:28px;line-height:1.3}.sg-feature h1{font-weight:400;font-size:36px;margin-bottom:18px}.sg-feature-excerpt{font-size:16px;line-height:1.6;color:var(--muted);margin-bottom:24px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.sg-author{display:flex;align-items:center;gap:16px;font-size:14px;line-height:1.6}.sg-avatar{border-radius:50%;width:40px;height:40px;background:#edf5ee;object-fit:cover;display:grid;place-items:center;color:#258b3e;font-weight:700}.sg-author a{color:#2875ce;font-weight:600}.sg-author small{display:block;font-size:14px;color:var(--muted)}.sg-feature-arrow{margin-left:auto;padding-left:8px}.sg-latest{margin-bottom:116px}.sg-section-title{font-size:28px;font-weight:700;margin-bottom:36px}.sg-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:24px}.sg-card{border:1px solid var(--line);border-radius:8px;overflow:hidden;display:flex;flex-direction:column;min-width:0;transition:box-shadow .2s}.sg-card:hover{box-shadow:0 3px 9px #0002}.sg-card-copy{padding:36px;flex:1;min-height:266px}.sg-card .sg-eyebrow{margin-bottom:28px}.sg-card h2{font-size:20px;font-weight:400;line-height:1.4;letter-spacing:-.2px}.sg-card-image{height:180px;background:#e8f3e9;display:block;overflow:hidden}.sg-card-image img{width:100%;height:100%;object-fit:cover;transition:transform .3s}.sg-card:hover .sg-card-image img{transform:scale(1.025)}.sg-list-heading{padding:60px 0 36px}.sg-list-heading h1{font-weight:400;font-size:42px}.sg-list-heading p{color:var(--muted);margin-top:10px}.sg-pager{display:flex;justify-content:center;gap:16px;margin-top:36px}.sg-empty{padding:60px 24px;text-align:center;background:var(--soft);border-radius:12px;color:var(--muted)}
/* Native popular posts */
.sg-popular{background:var(--mint);margin:0 0 80px}.sg-popular-row{display:grid;grid-template-columns:1fr 2fr;gap:40px;align-items:center}.sg-popular-intro{padding:40px 0}.sg-popular-intro h2{font-size:28px;margin-bottom:20px}.sg-popular-intro p{color:var(--muted);font-size:18px;margin-bottom:28px;max-width:360px}.sg-popular-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.sg-popular-card{background:var(--paper);border-radius:7px;overflow:hidden;border:1px solid var(--line);align-self:stretch}.sg-popular-image{height:220px;display:block;background:#daeedc}.sg-popular-image img{width:100%;height:100%;object-fit:cover}.sg-popular-copy{padding:24px;min-height:190px}.sg-popular-copy .sg-eyebrow{margin-bottom:15px}.sg-popular-copy h3{font-size:20px;font-weight:400;line-height:1.4}
/* Newsletter and footer */
.sg-newsletter{border:1px solid var(--line);border-radius:8px;padding:36px;margin-bottom:80px;text-align:center}.sg-newsletter h2{font-size:22px;font-weight:400;margin-bottom:28px}.sg-newsletter h2 span{color:#219340}.sg-newsletter form{display:flex;gap:12px;max-width:600px;margin:auto}.sg-newsletter input{padding:14px 16px;border:1px solid #9aa0a6;border-radius:4px;flex:1;min-width:0;color:var(--ink);background:var(--paper)}.sg-newsletter small{display:block;font-size:12px;color:var(--muted);margin-top:16px}.sg-newsletter small a{text-decoration:underline}.sg-newsletter-message{font-size:14px;margin-top:14px}.sg-footer{background:#f8f9fa;border-top:1px solid #e8eaed;font-size:14px;color:var(--muted)}.sg-social{display:flex;align-items:center;gap:30px;padding:30px 0;border-bottom:1px solid var(--line)}.sg-social ul{display:flex;gap:28px}.sg-social a{display:flex;align-items:center;gap:6px}.sg-social svg{width:20px;height:20px}.sg-footer-bottom{display:flex;align-items:center;gap:36px;padding:38px 0;flex-wrap:wrap}.sg-footer-bottom nav{display:flex;gap:20px}.sg-footer-bottom .sg-brand{font-size:23px}.sg-copyright{margin-left:auto;font-size:12px}.sg-credit{font-size:12px;padding-bottom:20px;color:#80868b}.sg-credit a{color:#219340}
/* Post layout */
.sg-post-head{max-width:800px;margin:40px auto 34px;padding:0 24px}.sg-post-meta{display:flex;align-items:center;flex-wrap:wrap;gap:9px;color:var(--muted);font-size:13px;margin-bottom:18px}.sg-post-meta .sg-eyebrow{font-size:12px;letter-spacing:.2px;background:#f0fff4;border-radius:20px;padding:3px 12px;margin:0}.sg-post-head h1{font-size:42px;font-weight:400;letter-spacing:-1.4px;margin-bottom:26px}.sg-post-author-row{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e8eaed;padding-top:20px;gap:18px}.sg-post-cover{max-width:1000px;margin:0 auto 42px;padding:0 0}.sg-post-cover img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:8px}.sg-prose-wrap{max-width:800px;margin:0 auto;padding:0 34px}.sg-post-body{font-size:17px;line-height:1.8;color:#3c4043}.sg-post-body>p{margin:0 0 24px}.sg-post-body h2{font-size:28px;font-weight:600;color:var(--ink);margin:50px 0 22px;padding-bottom:14px;border-bottom:1px solid #f1f3f4;scroll-margin-top:88px}.sg-post-body h3{font-size:22px;color:var(--ink);font-weight:500;margin:32px 0 18px;scroll-margin-top:88px}.sg-post-body h4{font-size:19px}.sg-post-body a{color:#258b3e;text-decoration:underline;text-underline-offset:3px}.sg-post-body ul,.sg-post-body ol{padding-left:26px;margin:20px 0 28px;list-style:disc}.sg-post-body ol{list-style:decimal}.sg-post-body li{padding-left:4px;margin:6px 0}.sg-post-body img{display:block;border-radius:8px;height:auto;max-width:100%;cursor:zoom-in}.sg-post-body img[data-lightbox=false]{cursor:auto}.sg-post-body iframe,.sg-post-body video{max-width:100%;border:0}.sg-post-body iframe[src*='youtube']{aspect-ratio:16/9;width:100%;height:auto}.sg-post-body figure{margin:30px 0}.sg-post-body figure img{width:100%}.sg-post-body figcaption{font-size:13px;color:var(--muted);text-align:center;margin-top:12px}.sg-post-body blockquote{border-left:4px solid var(--green);background:#f5fbf6;margin:30px 0;padding:22px 28px;font-size:20px;line-height:1.7}.sg-post-body cite{font-size:13px;color:var(--muted);display:block;margin-top:12px}.sg-post-body code{font:13px/1.6 Consolas,monospace;background:#f1f3f4;color:#b24a42;border:1px solid #e8eaed;border-radius:3px;padding:3px 5px;overflow-wrap:anywhere}.sg-post-body kbd{font:13px Consolas,monospace;border:1px solid #dadce0;border-bottom-width:3px;padding:3px 7px;border-radius:4px;background:#f8f9fa}.sg-post-body pre{white-space:pre;overflow:auto;max-width:100%;padding:20px;font:13px/1.7 Consolas,monospace;background:#f7f8fa;margin:26px 0;border:1px solid var(--line);border-radius:8px}.sg-post-body pre code{background:none;border:0;color:inherit;font:inherit;padding:0;overflow-wrap:normal}.sg-code-card{border:1px solid var(--line);border-radius:8px;overflow:hidden;margin:28px 0;background:#f8f9fa}.sg-code-card header{display:flex;gap:12px;align-items:center;padding:8px 12px;background:#eef0f2;border-bottom:1px solid var(--line);font:12px Consolas,monospace;color:var(--muted)}.sg-code-dots{display:flex;gap:6px;margin-right:8px}.sg-code-dots i{height:9px;width:9px;border-radius:50%;background:#ea635c}.sg-code-dots i:nth-child(2){background:#f5bf4f}.sg-code-dots i:nth-child(3){background:#54b765}.sg-code-card button{margin-left:auto;border:1px solid var(--line);border-radius:4px;padding:5px 10px;font:12px Arial,sans-serif;background:#fff;color:#202124}.sg-code-card pre{margin:0;border:0;border-radius:0;background:none}.sg-table-scroll{overflow-x:auto;margin:28px 0;border:1px solid var(--line);border-radius:8px}.sg-post-body table{width:100%;border-collapse:collapse;font-size:14px}.sg-post-body th,.sg-post-body td{padding:14px 18px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;min-width:120px}.sg-post-body th{background:#f2f7f3;font-weight:600;color:var(--ink)}.sg-post-body tr:last-child td{border-bottom:0}.sg-post-body .sg-lead,.sg-post-body .leaf-lead{font-size:18px;color:var(--muted)}.sg-dropcap,.leaf-dropcap{float:left;font-size:62px;line-height:1;margin:5px 10px 0 0;color:#289c41}.sg-callout,.leaf-callout{padding:18px 22px!important;border-left:3px solid #3cb85a;border-radius:4px;background:#f1fbf3;margin:24px 0;font-size:16px}.sg-callout>b,.leaf-callout>b{display:block;margin-bottom:4px;color:#237d38}.sg-callout--info,.leaf-callout--info{background:#eef5ff;border-color:#4285f4}.sg-callout--info>b,.leaf-callout--info>b{color:#2464bc}.sg-callout--warn,.leaf-callout--warn{background:#fff8e6;border-color:#f2b626}.sg-callout--warn>b,.leaf-callout--warn>b{color:#946000}.sg-callout--danger,.leaf-callout--danger{background:#fff0ef;border-color:#e65b55}.sg-callout--danger>b,.leaf-callout--danger>b{color:#b13732}.sg-media-grid,.leaf-media-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:28px 0}.sg-media-grid img,.leaf-media-grid img{width:100%;height:100%;aspect-ratio:4/3;object-fit:cover}.sg-file-card,.leaf-file-card{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid var(--line);border-radius:8px;padding:20px;margin:28px 0;line-height:1.5}.sg-file-info,.leaf-file-info{display:flex;align-items:center;gap:16px;min-width:0}.sg-file-badge,.leaf-file-badge{font-size:12px;font-weight:700;letter-spacing:1px;flex:none;background:#eef6ef;color:#27863a;padding:16px 11px;border-radius:7px}.sg-file-meta,.leaf-file-meta{display:flex;flex-direction:column;min-width:0}.sg-file-name,.leaf-file-name{font-size:15px;font-weight:600;color:var(--ink)}.sg-file-size,.leaf-file-size{font-size:12px;color:var(--muted)}.sg-post-body .sg-file-card .sg-btn,.sg-post-body .leaf-btn{padding:10px 18px;background:var(--green);color:#fff;border-radius:4px;text-decoration:none;font-size:14px;white-space:nowrap}.sg-faq-item,.leaf-faq-item{margin:12px 0;border:1px solid var(--line);border-radius:8px;overflow:hidden}.sg-faq-item summary,.leaf-faq-item summary{padding:18px 22px;font-size:16px;cursor:pointer;font-weight:500;list-style:none;display:flex;align-items:center;gap:18px;justify-content:space-between}.sg-faq-item summary:after,.leaf-faq-item summary:after{content:'+';font-size:24px;line-height:1}.sg-faq-item[open] summary:after,.leaf-faq-item[open] summary:after{content:'\2212 '}.sg-faq-item summary::-webkit-details-marker,.leaf-faq-item summary::-webkit-details-marker{display:none}.sg-faq-body,.leaf-faq-body{padding:0 22px 20px;font-size:15px;color:var(--muted)}.sg-toc{border:1px solid var(--line);background:#f8fbf8;border-radius:8px;margin:26px 0 36px;font-size:15px}.sg-toc summary{padding:16px 22px;font-weight:500;cursor:pointer;color:var(--ink)}.sg-toc ol{list-style:none;padding:0 22px 20px;margin:0}.sg-toc li{margin:6px 0;padding:0;line-height:1.6}.sg-toc li.sub{padding-left:20px;font-size:14px}.sg-toc a{text-decoration:none;color:var(--muted)}.sg-toc a:hover{color:#219340}.sg-post-tags{border-top:1px solid var(--line);display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:30px 0;margin-top:42px;font-size:12px}.sg-post-tags a{border-radius:18px;background:#f1f3f4;padding:5px 14px;color:var(--muted)}.sg-post-nav{display:flex;justify-content:space-between;gap:24px;border-top:1px solid var(--line);padding:24px 0;font-size:15px}.sg-post-nav a{flex:1}.sg-post-nav a:last-child{text-align:right}.sg-post-nav small{display:block;font-size:10px;letter-spacing:1px;color:var(--muted);margin-bottom:5px}.sg-comments{border-top:1px solid var(--line);padding:28px 0 50px;min-height:150px}.sg-comments h3{font-size:22px;margin-bottom:24px}.sg-comments iframe{max-width:100%}.sg-comments ol{list-style:none;padding:0}.sg-comments .comment{padding:16px 0;border-bottom:1px solid var(--line)}.sg-single{margin-bottom:80px}.sg-lightbox{padding:18px;background:#101513ed;border:0;max-width:100vw;max-height:100dvh;width:100vw;height:100dvh;color:#fff}.sg-lightbox::backdrop{background:#101513e8}.sg-lightbox-inner{display:grid;place-items:center;height:100%;padding:42px 34px}.sg-lightbox img{max-width:100%;max-height:calc(100dvh - 140px);width:auto;object-fit:contain}.sg-lightbox-close{position:absolute;top:10px;right:14px;color:#fff}.sg-lightbox-caption{font-size:14px;text-align:center;margin-top:16px}.sg-toast{position:fixed;z-index:150;bottom:24px;left:50%;transform:translateX(-50%);background:#26372b;color:#fff;padding:10px 20px;border-radius:6px;box-shadow:0 2px 10px #0003;font-size:14px;max-width:calc(100% - 32px);text-align:center}
/* Optional local preference */
html.sg-dark{--paper:#202124;--ink:#e8eaed;--muted:#bdc1c6;--line:#45494d;--soft:#292d30;--mint:#183121}html.sg-dark .sg-brand{color:#c8efcf}html.sg-dark .sg-footer{background:#26292b}html.sg-dark .sg-feature-copy{border-color:var(--line)}html.sg-dark .sg-post-body{color:#dadce0}html.sg-dark .sg-toc,html.sg-dark .sg-post-body blockquote{background:#27362b}html.sg-dark .sg-code-card,html.sg-dark .sg-code-card header,html.sg-dark .sg-post-body code,html.sg-dark .sg-post-body kbd{background:#292d30}html.sg-dark .sg-post-body th{background:#293c2e}html.sg-dark .sg-post-tags a{background:#303438}html.sg-dark .sg-callout,html.sg-dark .leaf-callout{color:#202124}
/* Blogger layout editor: gadgets remain editable and visible here. */
