n-height:176px;padding:24px}.sg-popular-copy h3{font-size:20px}.sg-newsletter{padding:30px 20px;margin-bottom:48px}.sg-newsletter h2{font-size:22px;line-height:1.5}.sg-newsletter form{flex-direction:column}.sg-newsletter input{width:100%}.sg-social{gap:20px;flex-wrap:wrap;padding:28px 0}.sg-social ul{gap:24px;flex-wrap:wrap}.sg-social a span{display:none}.sg-footer-bottom{align-items:flex-start;flex-direction:column;gap:26px;padding:30px 0}.sg-footer-bottom nav{flex-wrap:wrap;font-size:13px;gap:18px}.sg-mega-grid{grid-template-columns:1fr;gap:22px}.sg-mega h3{padding-bottom:10px;margin-bottom:8px}.sg-search{padding:18px 16px}.sg-search form{flex-wrap:wrap}.sg-search .sg-btn{padding:10px 16px}.sg-post-head{margin:28px auto 30px;padding:0 20px}.sg-post-head h1{font-size:30px;letter-spacing:-.7px;margin-bottom:26px}.sg-post-meta{font-size:11px;gap:6px}.sg-post-meta .sg-eyebrow{font-size:10px;padding:3px 10px}.sg-post-author-row{gap:10px;padding-top:18px}.sg-post-author-row .sg-pill{font-size:11px;padding:7px 12px}.sg-post-cover{padding:0 16px;margin-bottom:30px}.sg-prose-wrap{padding:0 20px}.sg-post-body{font-size:16px;line-height:1.8}.sg-post-body h2{font-size:24px;margin-top:38px}.sg-post-body h3{font-size:20px}.sg-post-body .sg-lead,.sg-post-body .leaf-lead{font-size:17px}.sg-post-body blockquote{font-size:18px;padding:20px}.sg-callout,.leaf-callout{padding:16px 18px!important;font-size:15px}.sg-media-grid,.leaf-media-grid{grid-template-columns:1fr}.sg-file-card,.leaf-file-card{flex-wrap:wrap;padding:16px}.sg-file-card .sg-btn,.leaf-file-card .leaf-btn{width:100%}.sg-post-body pre{font-size:12px;padding:16px}.sg-faq-item summary,.leaf-faq-item summary{padding:16px;font-size:15px}.sg-faq-body,.leaf-faq-body{padding:0 16px 16px}.sg-list-heading{padding-top:36px}.sg-list-heading h1{font-size:32px}.sg-single{margin-bottom:44px}.sg-lightbox-inner{padding:35px 0}.sg-lightbox{padding:12px}}
