/* Leaf-style navigation and search interactions. */
.sg-navigation{flex:1;min-width:0}.sg-drawer-brand,.sg-mobile-extras,.sg-mega-back{display:none}.sg-nav-overlay{position:fixed;inset:0;z-index:100;width:100%;height:100dvh;background:#0008;border:0;padding:0;cursor:default;animation:sgOverlayIn .35s ease}.sg-search{position:absolute;top:4px;right:24px;left:auto;width:min(720px,calc(100vw - 260px));padding:0;background:transparent;box-shadow:none;z-index:103;animation:sgSearchIn .35s ease}.sg-search-surface{background:var(--mint);color:var(--ink);border-radius:8px;padding:0 16px;box-shadow:0 4px 16px #3c404340,0 2px 6px #3c404326;max-height:calc(100dvh - 12px);overflow:auto;overscroll-behavior:contain}.sg-search form{display:flex;align-items:center;gap:0;height:56px;border-bottom:1px solid var(--line);max-width:none}.sg-search .sg-icon{width:40px;height:48px;color:var(--muted);flex:none;padding:8px}.sg-search input{min-width:0;flex:1;width:100%;height:48px;border:0;border-radius:0;padding:0 10px;background:transparent;color:var(--ink);font-size:16px;outline:none;box-shadow:none}.sg-search input:focus-visible{outline:none}.sg-search input::-webkit-search-cancel-button{-webkit-appearance:none}.sg-search-content{padding:24px 0}.sg-search-description{font-size:18px;line-height:1.6;color:var(--muted);margin:0}.sg-search-heading{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:500;letter-spacing:0;line-height:24px;margin:24px 0 16px}.sg-search-heading svg{width:24px;height:24px}.sg-search-suggestions{display:flex;gap:8px;flex-wrap:wrap;list-style:none;padding:0;margin:0}.sg-search-suggestions a{display:flex;align-items:center;border-radius:48px;background:#e8f0fe;color:#174ea6;padding:12px 16px;min-height:48px;font-size:14px;line-height:24px}.sg-search-suggestions a:hover{background:#d2e3fc;color:#174ea6}.sg-search-open .sg-actions{visibility:hidden}.sg-mega-back{align-items:center;gap:8px}.sg-group-toggle{font:inherit;text-transform:inherit;letter-spacing:inherit;width:100%;padding:0;display:flex;align-items:center;justify-content:space-between;text-align:left}.sg-group-toggle .sg-chevron{display:none}.sg-mega-grid h3{margin:0 0 16px}.sg-group-links{margin:0;padding:0}.sg-header.reading .sg-navigation{display:none}
@keyframes sgSearchIn{from{opacity:0;transform:translateX(2%)}to{opacity:1;transform:translateX(0)}}@keyframes sgOverlayIn{from{opacity:0}to{opacity:1}}@keyframes sgSubmenuIn{from{transform:translateX(100%)}to{transform:translateX(0)}}
/* Constrain article content instead of clipping the document. Oversized tables/code scroll locally. */
.sg-main,.sg-single,.sg-prose-wrap,.sg-post-body{min-width:0;max-width:100%}.sg-prose-wrap{width:min(800px,100%)}.sg-post-body>*{max-width:100%;min-width:0}.sg-post-body .separator,.sg-post-body .tr-caption-container{max-width:100%!important;margin-left:0!important;margin-right:0!important}.sg-post-body .separator a{display:block;max-width:100%;margin-left:0!important;margin-right:0!important}.sg-post-body img,.sg-post-body video,.sg-post-body iframe,.sg-post-body object,.sg-post-body embed{max-width:100%!important}.sg-post-body img{height:auto!important}.sg-post-body pre,.sg-code-card,.sg-table-scroll{width:100%;min-width:0;max-width:100%}.sg-post-body pre{overflow-x:auto;overflow-wrap:normal;overscroll-behavior-x:contain}.sg-table-scroll{overflow-x:auto;overscroll-behavior-x:contain}.sg-post-body blockquote{margin-left:0;margin-right:0}.sg-post-body iframe[width]{width:min(100%,1000px)}.sg-post-body .sg-content-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}
@media(max-width:1023.98px){
 .sg-mobile-toggle{display:inline-flex}.sg-header-row{padding:0 12px;gap:8px}.sg-actions .sg-subscribe,.sg-actions .sg-more-toggle{display:none}.sg-header.reading .sg-navigation{display:flex}
 .sg-navigation{display:flex;flex-direction:column;position:fixed;left:0;top:0;bottom:0;width:85%;max-width:380px;height:100dvh;background:var(--paper);z-index:101;overflow:hidden;box-shadow:2px 0 8px #0002;transform:translateX(-105%);visibility:hidden;pointer-events:none;transition:transform .35s cubic-bezier(.24,1,.32,1),visibility 0s .35s}
 .sg-navigation.is-open{transform:translateX(0);visibility:visible;pointer-events:auto;transition:transform .35s cubic-bezier(.24,1,.32,1),visibility 0s}
 .sg-drawer-brand{display:flex;align-items:center;gap:8px;height:64px;min-height:64px;padding:0 12px;border-bottom:1px solid var(--line)}.sg-drawer-brand>.sg-icon{width:40px;height:48px;padding:8px}.sg-drawer-brand .sg-brand{font-size:21px}.sg-drawer-brand .sg-tagline{font-size:16px!important;max-width:none!important;margin:0;min-width:0;overflow:hidden;text-overflow:ellipsis;display:block!important}.sg-drawer-brand .sg-brand-image{max-width:140px}
 .sg-nav-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain}.sg-nav{display:block;position:static;height:auto;max-height:none;padding:16px 16px 16px 0;overflow:visible;box-shadow:none;background:transparent;font-size:16px}.sg-nav>li{display:block;padding-left:24px}.sg-nav>li>a,.sg-nav>li>button{display:flex;align-items:center;justify-content:space-between;gap:12px;height:52px;line-height:1.3;width:100%;padding:0 12px 0 0;border:0;font-weight:500;color:var(--muted);border-radius:0;background:transparent}.sg-nav>li:has(>a[aria-current=page]){border-radius:0 20px 20px 0;background:#f5f5f5}.sg-nav>li>a[aria-current=page]{border:0;color:#202124}.sg-nav>li>button>.sg-chevron{transform:rotate(-90deg);width:18px;height:18px}.sg-nav>li>button[aria-expanded=true]{background:transparent}
 .sg-mobile-extras{display:block}.sg-mobile-extras ul{border-top:1px solid var(--line);padding:16px 24px}.sg-mobile-extras li a{display:flex;align-items:center;height:48px;font-size:16px;color:#757575}.sg-mobile-extras>.sg-btn{display:flex;margin:0 24px 24px;min-height:48px;border-radius:3px;font-size:16px}
 .sg-mega{position:absolute;top:64px;bottom:0;left:0;right:0;width:100%;max-height:none;background:var(--paper);box-shadow:none;border-radius:0;padding:0;overflow-x:hidden;overflow-y:auto;z-index:102;overscroll-behavior:contain;animation:sgSubmenuIn .4s cubic-bezier(.24,1,.32,1)}.sg-mega-back{display:flex;width:100%;height:52px;padding:0 24px;color:var(--muted);font-size:16px;text-align:left}.sg-mega-back .sg-chevron{transform:rotate(90deg);width:16px;height:16px}.sg-mega-grid{display:block;border-top:1px solid var(--line);margin:0 16px;padding:12px 0}.sg-mega-grid h3{padding:0;margin:0;border:0;text-transform:none;letter-spacing:0;color:var(--muted);font-weight:500;font-size:16px}.sg-group-toggle{min-height:52px;padding:10px 48px 10px 32px;line-height:1.5;gap:16px}.sg-group-toggle .sg-chevron{display:block;flex:none;width:18px;height:18px;transition:transform .35s}.sg-group-toggle[aria-expanded=true] .sg-chevron{transform:rotate(180deg)}.sg-group-links{padding:0 0 8px}.sg-mega .sg-group-links li a{padding:12px 20px 12px 38px;font-size:14px;line-height:1.3;color:#757575}.sg-mega-close{display:none}.sg-mega-bottom{justify-content:flex-start;padding:16px 32px 24px;margin:0 16px;border-top:1px solid var(--line);font-size:14px;color:#45b961}
 .sg-search{top:4px;left:12px;right:12px;width:auto}.sg-search form{flex-wrap:nowrap}.sg-search-surface{padding:0 16px}.sg-search-suggestions{flex-direction:column;align-items:flex-start}.sg-search-suggestions a{max-width:100%}.sg-header .sg-navigation .sg-brand{flex:none}
}
body#layout .sg-navigation{position:static!important;transform:none;visibility:visible;display:none!important}body#layout .sg-nav-overlay,body#layout .sg-search{display:none!important}

html{overscroll-behavior-x:none}.sg-slides{touch-action:pan-y}.sg-search-suggestions{overflow-wrap:anywhere}


/* SaeGreen 1.0.2 — pointer/touch focus and layout groups. */
.sg-header button,.sg-header a,.sg-header select{-webkit-tap-highlight-color:transparent}
.sg-region:focus-within{outline:none;box-shadow:none}
html:not(.sg-keyboard) button:focus,html:not(.sg-keyboard) a:focus,html:not(.sg-keyboard) select:focus,html:not(.sg-keyboard) summary:focus{outline:none!important;box-shadow:none!important}
.sg-keyboard .sg-region:focus-within{outline:3px solid #2884f4;outline-offset:2px}
body#layout .sg-cfg,#layout .sg-cfg{margin:16px 0!important;padding:16px!important;border:1px solid #bddcc4!important;border-radius:10px;background:#f1fbf4!important}
body#layout .sg-cfg .widget,#layout .sg-cfg .widget{margin:10px 0!important;min-width:0}
body#layout .sg-legacy-cfg,#layout .sg-legacy-cfg{background:#f5f5f5!important;border-color:#d1d5d3!important}
/* SaeGreen article components 1.1: reusable HTML examples and documentation. */
.sg-post-body .sg-guide{min-width:0}
.sg-post-body .sg-guide-kicker{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#258c42;font-weight:700;margin-bottom:12px}
.sg-post-body .sg-guide-intro{font-size:20px;line-height:1.65;color:var(--muted);margin-bottom:24px}
.sg-post-body .sg-guide-stats{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0 32px}
.sg-post-body .sg-guide-stats span,.sg-post-body .sg-badge{display:inline-flex;align-items:center;border:1px solid #c8e4cf;background:var(--mint);color:var(--ink);border-radius:30px;padding:5px 12px;font-size:12px;line-height:1.5}
.sg-post-body .sg-guide-nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:28px 0}
.sg-post-body .sg-guide-nav a{display:block;padding:18px;border:1px solid var(--line);border-radius:12px;text-decoration:none;font-size:14px;color:var(--ink);background:var(--paper)}
.sg-post-body .sg-guide-nav a:hover{border-color:#3dcc58;background:var(--mint)}
.sg-post-body .sg-guide-nav small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#258c42;margin-bottom:5px}
.sg-post-body .sg-demo{position:relative;min-width:0;margin:22px 0 34px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--paper)}
.sg-post-body .sg-demo-choice{position:absolute;width:1px;height:1px;padding:0;margin:0;opacity:0;overflow:hidden;clip-path:inset(50%)}
.sg-post-body .sg-demo-tabs{display:flex;align-items:center;gap:4px;padding:8px;background:var(--soft);border-bottom:1px solid var(--line)}
.sg-post-body .sg-demo-tabs label{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:8px 18px;border-radius:7px;font:500 13px/1.4 'Google Sans',Arial,sans-serif;cursor:pointer;color:var(--muted)}
.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(1):checked~.sg-demo-tabs label:nth-child(1),.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(2):checked~.sg-demo-tabs label:nth-child(2),.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(3):checked~.sg-demo-tabs label:nth-child(3){background:var(--paper);color:#23823c;box-shadow:0 1px 4px #0001}
.sg-post-body .sg-demo>.sg-demo-choice:focus-visible~.sg-demo-tabs{outline:2px solid #2884f4;outline-offset:-3px}
.sg-post-body .sg-demo-panel{display:none;padding:24px;min-width:0}
.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(1):checked~.sg-demo-panel:nth-of-type(2),.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(2):checked~.sg-demo-panel:nth-of-type(3),.sg-post-body .sg-demo>.sg-demo-choice:nth-of-type(3):checked~.sg-demo-panel:nth-of-type(4){display:block}
.sg-post-body .sg-demo-panel>*:first-child{margin-top:0}.sg-post-body .sg-demo-panel>*:last-child{margin-bottom:0}
.sg-post-body .sg-demo-code{padding:0;background:#17231d;color:#e0f0e5}
.sg-post-body .sg-demo-code .sg-code-card{margin:0;border:0;border-radius:0;background:#17231d}
.sg-post-body .sg-demo-code .sg-code-card header{background:#213329;color:#c1d5c7;border-color:#365440}
.sg-post-body .sg-demo-code pre{margin:0;border:0;border-radius:0;background:#17231d;color:#e0f0e5;max-height:440px;tab-size:2}
.sg-post-body .sg-demo-code code{color:inherit;background:none}
.sg-post-body .sg-demo-code .sg-code-card button{background:#2c4936;color:#e6f4ea;border-color:#467b55}
.sg-post-body .sg-indent{text-indent:2em}
.sg-post-body .sg-note-source{font-size:13px;color:var(--muted);border-top:1px solid var(--line);padding-top:16px}
.sg-post-body .sg-steps{list-style:none;counter-reset:sg-step;padding:0;margin:24px 0}
.sg-post-body .sg-steps>li{position:relative;counter-increment:sg-step;padding:0 0 24px 48px;margin:0;min-height:44px}
.sg-post-body .sg-steps>li:before{content:counter(sg-step,decimal-leading-zero);position:absolute;top:0;left:0;width:32px;height:32px;display:grid;place-items:center;border:1px solid #bedec6;border-radius:10px;background:var(--mint);color:#268640;font:700 12px/1 Arial,sans-serif}
.sg-post-body .sg-steps strong{display:block;color:var(--ink);margin-bottom:4px}
.sg-post-body .sg-checklist{list-style:none;padding:0;margin:20px 0}.sg-post-body .sg-checklist li{position:relative;padding:6px 0 6px 30px;margin:0}.sg-post-body .sg-checklist li:before{content:'\2713 ';position:absolute;left:0;color:#258c42;font-weight:700}
.sg-post-body .sg-button-row{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.sg-post-body .sg-button-row a{text-decoration:none;min-height:44px}
.sg-post-body .sg-button-row .sg-btn{color:#fff}
.sg-post-body .sg-btn-outline{display:inline-flex;align-items:center;justify-content:center;padding:11px 24px;border:1px solid #50aa66;color:#258c42;background:transparent;border-radius:4px;font-size:14px;text-decoration:none}
.sg-post-body .sg-external:after{content:' \2197 ';font-size:.9em}
.sg-post-body .sg-gallery-scroll{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-x:contain;padding:2px 0 12px;max-width:100%}
.sg-post-body .sg-gallery-scroll figure{flex:0 0 76%;scroll-snap-align:start;margin:0}.sg-post-body .sg-gallery-scroll img{width:100%;aspect-ratio:4/3;object-fit:cover}
.sg-post-body .sg-gallery-more{border:1px solid var(--line);border-radius:10px;padding:16px;margin:20px 0}.sg-post-body .sg-gallery-more>summary{cursor:pointer;color:#258c42;font-size:14px;min-height:32px}.sg-post-body .sg-gallery-more .sg-media-grid{margin-bottom:0}
