.sg-post-body .sg-related{padding:22px;border:1px solid var(--line);border-radius:12px;margin:28px 0;background:var(--mint)}.sg-post-body .sg-related>strong{display:block;margin-bottom:10px;color:var(--ink)}.sg-post-body .sg-related ul{margin:0;padding-left:20px}
.sg-post-body .sg-video{position:relative;aspect-ratio:16/9;background:#193526;border:1px solid #325c40;border-radius:12px;overflow:hidden;margin:24px 0;color:#fff;display:grid;place-items:center}
.sg-post-body .sg-video button{padding:24px;min-height:44px;color:#fff;font-size:16px}.sg-post-body .sg-video button:before{content:'\25b6 ';display:block;font-size:32px;margin-bottom:8px;color:#81ec99}.sg-post-body .sg-video iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.sg-post-body .sg-tab-content{border:1px solid var(--line);border-radius:10px;padding:20px;background:var(--soft)}
.sg-post-body .sg-guide table caption{text-align:left;font-size:12px;color:var(--muted);padding:12px}
@media(max-width:600px){.sg-post-body .sg-guide-intro{font-size:18px}.sg-post-body .sg-guide-nav{grid-template-columns:1fr}.sg-post-body .sg-guide-nav a{padding:14px 16px}.sg-post-body .sg-demo-panel{padding:18px}.sg-post-body .sg-demo-code{padding:0}.sg-post-body .sg-demo-tabs label{padding:8px 14px}.sg-post-body .sg-demo-code pre{font-size:12px}.sg-post-body .sg-content-card{padding:18px}}
