/* SaeGreen 1.2.1: product section only; original blog layout preserved. */
.sg-store-section{padding-top:24px;padding-bottom:60px;scroll-margin-top:88px}.sg-store-header{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin-bottom:26px}.sg-store-header p{font-size:14px;line-height:1.7;color:var(--muted);margin-top:9px;max-width:680px}.sg-store-header>a{white-space:nowrap;font-size:12px}.sg-store-grid{--store-columns:3;--store-mobile-columns:2;display:grid;grid-template-columns:repeat(var(--store-columns),minmax(0,1fr));gap:22px;min-width:0}.sg-store-card{display:flex;flex-direction:column;min-width:0;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--paper);transition:box-shadow .18s}.sg-store-card:hover{box-shadow:0 5px 22px #153f2410}.sg-store-image{display:block;position:relative;aspect-ratio:16/10;background:var(--mint);overflow:hidden}.sg-store-image img{display:block;width:100%;height:100%;object-fit:contain}.sg-store-promo{position:absolute;top:12px;left:12px;right:12px;display:flex;gap:5px;flex-wrap:wrap;pointer-events:none}.sg-store-badge{font-size:10px;line-height:1.4;padding:5px 8px;border-radius:5px;background:#fff3d8;color:#7d5b12;border:1px solid #e8d6a6;max-width:100%}.sg-store-badge-demo{background:var(--paper);color:var(--muted);border-color:var(--line)}.sg-store-copy{padding:22px;display:flex;flex-direction:column;flex:1}.sg-store-copy small{color:#278c45;font-size:10px;letter-spacing:.08em;text-transform:uppercase}.sg-store-copy h3{font-size:20px;line-height:1.35;font-weight:500;margin:10px 0 12px;letter-spacing:-.4px}.sg-store-copy>p{font-size:12px;color:var(--muted);line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:17px}.sg-store-prices{margin-top:auto;padding-top:5px}.sg-store-prices del{font-size:12px;color:var(--muted);display:block;margin-bottom:3px}.sg-store-price-line{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.sg-store-price-line strong{font-size:23px;letter-spacing:-.5px;font-weight:600}.sg-store-discount{font-size:10px;padding:3px 7px;border-radius:4px;background:#dff1e3;color:#236d36}.sg-store-detail{margin-top:18px;padding-top:14px;border-top:1px solid var(--line);font-size:12px;color:#278c45;display:flex;justify-content:space-between;align-items:center}.sg-store-detail svg{width:16px;height:16px}.sg-store-empty{grid-column:1/-1;min-height:170px;padding:40px 25px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);font-size:14px;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:12px}.sg-store-empty button{padding:9px 16px;border:1px solid var(--line);border-radius:6px;background:var(--paper);font-size:12px}.sg-store-catalog .sg-list-heading{padding-top:48px;padding-bottom:30px}.sg-store-catalog .sg-list-heading h1{font-size:40px;font-weight:600}.sg-store-catalog .sg-list-heading p{font-size:14px;line-height:1.8;max-width:760px}.sg-store-catalog .sg-pager{margin-top:32px}
.sg-store-header h2{font-size:28px;font-weight:700}.sg-home-kicker{color:#258e46;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;margin-bottom:16px}
.sg-mega-grid:has(>.sg-menu-group:only-child){grid-template-columns:1fr;max-width:680px}.sg-social:has(ul:empty){display:none}
html.sg-dark .sg-store-copy small,html.sg-dark .sg-store-detail{color:#8fd59e}html.sg-dark .sg-store-discount{background:#2a4b33;color:#c9ebcf}
@media(min-width:1024px) and (max-width:1240px){.sg-header-row{gap:12px;padding-right:18px}.sg-header .sg-tagline{display:none}.sg-nav{gap:2px;font-size:13px}.sg-nav>li>a,.sg-nav>li>button{padding:0 10px}.sg-actions{gap:4px}.sg-actions .sg-subscribe{font-size:12px;padding:9px 13px}}
