@media(max-width:600px){.sg-store-section{padding-top:10px;padding-bottom:42px}.sg-store-header{display:block;margin-bottom:20px}.sg-store-header h2{font-size:24px}.sg-store-header p{font-size:12px;margin-bottom:15px}.sg-store-header>a{display:inline-flex;font-size:11px;padding:7px 13px}.sg-store-grid{grid-template-columns:repeat(var(--store-mobile-columns),minmax(0,1fr));gap:12px}.sg-store-copy{padding:14px}.sg-store-copy h3{font-size:16px;margin:8px 0 10px}.sg-store-copy>p{font-size:11px;margin-bottom:12px}.sg-store-price-line strong{font-size:19px}.sg-store-prices del{font-size:11px}.sg-store-price-line{gap:5px}.sg-store-discount{font-size:9px}.sg-store-promo{top:7px;left:7px;right:7px}.sg-store-badge{font-size:9px;padding:3px 5px}.sg-store-detail{font-size:11px;margin-top:14px;padding-top:12px}.sg-store-catalog .sg-list-heading{padding-top:32px}.sg-store-catalog .sg-list-heading h1{font-size:32px}.sg-store-catalog .sg-list-heading p{font-size:13px}}
