/* SaeGreen 1.2.2: image-first article cards and responsive footer. */
.sg-latest .sg-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;align-items:stretch}
.sg-latest .sg-card{display:flex;flex-direction:column;padding:0;gap:0;min-height:0;border-radius:12px;background:var(--paper)}
.sg-latest .sg-card-image{display:block;order:0;width:100%;height:auto;aspect-ratio:16/9;flex:none;margin:0;align-self:auto;border-radius:0;border-bottom:1px solid var(--line)}
.sg-latest .sg-card-image img{display:block;width:100%;height:100%;object-fit:cover}
.sg-latest .sg-card-copy{order:1;min-height:0;padding:22px;flex:1}
