.sg-latest .sg-card h2{font-size:19px;font-weight:500;line-height:1.45;letter-spacing:-.3px;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}
.sg-latest .sg-section-title{margin-bottom:26px}.sg-home .sg-latest{margin-bottom:46px}
.sg-popular{margin-bottom:0}.sg-popular-row{padding-top:36px;padding-bottom:36px}.sg-popular-intro{padding:0}.sg-popular-cards{padding-bottom:0}
.sg-footer{background:var(--soft);border-top:1px solid var(--line)}
.sg-footer-main{display:grid;grid-template-columns:1.1fr 1fr;gap:80px;padding:42px 0 30px;align-items:start}
.sg-footer-identity{min-width:0}.sg-footer-identity .sg-brand{display:inline-flex;font-size:25px}
.sg-footer-description{max-width:380px;margin-top:15px;color:var(--muted);font-size:13px;line-height:1.8}
.sg-footer-navigation{min-width:0}.sg-footer-navigation h2{font-size:13px;font-weight:600;letter-spacing:0;margin-bottom:12px;color:var(--ink)}
.sg-footer-navigation nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px 24px}
.sg-footer-navigation nav a{display:flex;align-items:center;min-height:38px;padding:5px 0;font-size:13px;line-height:1.5;overflow-wrap:anywhere}
.sg-footer .sg-footer-bottom{display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:16px 30px;padding:20px 0 24px;border-top:1px solid var(--line);flex-wrap:wrap}
.sg-footer .sg-copyright{margin:0;width:auto;font-size:12px;line-height:1.7}
.sg-footer .sg-credit{padding:0;margin:0;font-size:12px;line-height:1.7}
.sg-footer .sg-social{padding:0 0 24px;border-bottom:0;font-size:13px}.sg-footer .sg-social ul{flex-wrap:wrap}
@media(max-width:1100px){.sg-latest .sg-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.sg-latest .sg-card-copy{padding:20px}.sg-footer-main{gap:45px}}
@media(max-width:900px){.sg-latest .sg-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sg-popular-intro{padding-top:0}.sg-footer-main{grid-template-columns:1fr 1fr;gap:32px}}
@media(max-width:600px){.sg-latest .sg-grid{gap:18px}.sg-latest .sg-card h2{font-size:18px}.sg-latest .sg-card-copy{padding:20px}.sg-home .sg-latest{margin-bottom:36px}.sg-popular-row{padding-top:30px;padding-bottom:30px}.sg-popular-cards{padding-bottom:8px}.sg-footer-main{grid-template-columns:1fr;gap:27px;padding-top:30px;padding-bottom:24px}.sg-footer-description{font-size:12px;margin-top:12px;max-width:100%}.sg-footer-navigation h2{font-size:13px;margin-bottom:8px}.sg-footer-navigation nav{gap:0 18px}.sg-footer-navigation nav a{min-height:44px;font-size:12px}.sg-footer .sg-footer-bottom{align-items:flex-start;flex-direction:column;gap:7px;padding:18px 0 22px}.sg-footer .sg-copyright,.sg-footer .sg-credit{font-size:11px}.sg-footer .sg-social{gap:14px}.sg-footer .sg-social ul{gap:18px}}
