/* SaeGreen 1.2.3: compact product cards; descriptions stay on the detail page. */
.sg-store-copy>p{display:none}
@media(max-width:600px){
 .sg-store-grid{grid-template-columns:repeat(var(--store-mobile-columns),minmax(0,1fr));gap:10px}
 .sg-store-card{border-radius:10px}.sg-store-image{aspect-ratio:4/3}.sg-store-image img{object-fit:contain}
