 .sg-store-copy h3{font-size:13px;line-height:1.4;font-weight:500;letter-spacing:-.15px;margin:0 0 9px;min-height:2.8em;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
 .sg-store-prices{margin-top:auto;padding-top:0;min-height:42px;display:flex;flex-direction:column;justify-content:flex-end}
