 .sg-store-price-line strong{font-size:17px;line-height:1.3;letter-spacing:-.4px}.sg-store-discount{font-size:8px;padding:2px 4px;line-height:1.3}
 .sg-store-detail{font-size:10px;line-height:1.4;margin-top:11px;padding-top:9px;min-height:32px;gap:5px}
 .sg-store-promo{top:6px;left:6px;right:6px;gap:3px}.sg-store-badge{font-size:8px;padding:2px 5px;line-height:1.4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
}
@media(max-width:360px){.sg-store-copy{padding:10px}.sg-store-copy h3{font-size:12px}.sg-store-price-line strong{font-size:15px}.sg-store-discount{font-size:7px;padding:2px 3px}}


/* Shared skill SVG icons: neutral currentColor in light and dark themes. */
.sg-social-icon{width:32px;height:32px;display:block;flex:none}
.sg-footer .sg-social a{color:var(--muted)}.sg-footer .sg-social a:hover{color:var(--ink)}.sg-footer .sg-social svg{width:28px;height:28px}
.sg-article-share{display:flex;align-items:center;flex-wrap:wrap;gap:12px 16px;margin:32px 0;padding:22px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);color:var(--ink)}
.sg-share-title{font-size:14px;font-weight:500}.sg-article-share nav{display:flex;flex-wrap:wrap;gap:4px}
.sg-network-share{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;color:var(--muted)}.sg-network-share:hover{background:var(--soft);color:var(--ink)}
.sg-share-copy{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;color:var(--ink)}.sg-share-copy svg{width:20px;height:20px}
