.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}

/* TemaBlogger: CSS khusus panel native Blogger, kompatibel parser legacy. */
body#layout { min-width:0!important; max-width:1120px!important; margin:0 auto!important; padding:16px!important; background:#eef2f6!important; color:#26364c!important; font:14px/1.5 Arial,sans-serif!important; text-align:left!important; }
body#layout .tbly-pass { display:contents!important; }
body#layout .tbly-pass:before,body#layout .tbly-pass:after { content:none!important; display:none!important; }
body#layout .tbly-ignore { display:none!important; }
body#layout .tbly-group { display:block!important; clear:both!important; float:none!important; position:relative!important; top:auto!important; bottom:auto!important; left:auto!important; right:auto!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 20px!important; padding:18px!important; overflow:visible!important; transform:none!important; border:1px solid #d4deeb!important; border-radius:8px!important; background:#f8fafc!important; color:#26364c!important; text-align:left!important; }
body#layout .tbly-group:before { display:block!important; position:static!important; clear:both!important; margin:0 0 16px!important; padding:0 0 10px!important; border-bottom:1px solid #dce4ef!important; font:700 16px/1.4 Arial,sans-serif!important; color:#3dcc58!important; background:none!important; }
body#layout .tbly-group:after { display:block!important; position:static!important; clear:both!important; margin:0!important; padding:4px 0 0!important; font:12px/1.6 Arial,sans-serif!important; color:#60718a!important; background:none!important; }
body#layout div.section>h4 { margin:0 0 10px!important; padding:0!important; font:700 13px/1.5 Arial,sans-serif!important; color:#34455c!important; word-wrap:break-word!important; }
body#layout div.section .widget { float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:10px 0 0!important; }
body#layout div.section .widget-content { min-width:0!important; border-radius:6px!important; background:#fff!important; }
body#layout div.section .layout-title { color:#394b62!important; }
body#layout div.section .layout-widget-description { color:#6a7a90!important; }
body#layout div.section .editlink,body#layout div.section .layout-widget-state { visibility:visible!important; opacity:1!important; }
body#layout div.section .add_widget { display:none!important; }

body#layout:before { content:"SaeGreen - Pengaturan Tata Letak"; display:block; margin:0 0 18px; color:#3dcc58; font:700 22px/1.4 Arial,sans-serif; }
body#layout #saegreenSettings { display:block!important; position:relative!important; float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 14px!important; padding:12px!important; overflow:visible!important; background:#fff!important; border:1px solid #dbe2ec!important; border-radius:7px!important; text-align:left!important; }
